const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-04/');

  // TODO: Import { expect } from '@playwright/test' alongside chromium
  // Assert page.locator('h1') toHaveText 'Hall of Truth'
  // Assert page.locator('#hero-badge') toHaveClass /badge-gold/ then log: console.log('LEVEL_PASSED')

  await browser.close();
})();

solution:
const { chromium, expect } = require('@playwright/test');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-04/');
  await expect(page.locator('h1')).toHaveText('Hall of Truth');
  await expect(page.locator('#hero-badge')).toHaveClass(/badge-gold/);
  console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`expect(locator).toHaveText()` and `expect(locator).toHaveClass()` are Playwright Test assertions. Import `expect` from `@playwright/test`:

```
const { chromium, expect } = require('@playwright/test');
// ...
await expect(page.locator('h1')).toHaveText('Hall of Truth');
await expect(page.locator('#hero-badge')).toHaveClass(/badge-gold/);
console.log('LEVEL_PASSED');
```

Assertions automatically retry for up to 5 seconds — they wait for the element to match rather than failing immediately.

