  // TODO: Wait for '#treasure-chest[data-treasure="golden-key"]' to be visible (appears after 2s)
  // Use locator.waitFor({ state: 'visible', timeout: 10000 })
  // Then read its data-treasure attribute — if 'golden-key', log: console.log('LEVEL_PASSED')

  await browser.close();
})();

solution:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-05/');
  const chest = page.locator('#treasure-chest[data-treasure="golden-key"]');
  await chest.waitFor({ state: 'visible', timeout: 10000 });
  const value = await page.locator('#treasure-chest').getAttribute('data-treasure');
  if (value === 'golden-key') console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`locator.waitFor({ state: 'visible' })` pauses execution until the element becomes visible in the DOM. Set a `timeout` for elements that take longer:

```
const chest = page.locator('#treasure-chest[data-treasure="golden-key"]');
await chest.waitFor({ state: 'visible', timeout: 10000 });
const value = await page.locator('#treasure-chest').getAttribute('data-treasure');
if (value === 'golden-key') console.log('LEVEL_PASSED');
```

You can combine attribute selectors `[attr="value"]` directly inside `locator()` to find specific elements.

