const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-08/');

  // TODO: Use page.route('**/api/items', handler) BEFORE page.goto()
  // Inside the handler call route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify([{ name: 'dragon-scale' }]) })
  // After goto, wait for 'text=dragon-scale' then log: console.log('LEVEL_PASSED')

  await browser.close();
})();

solution:
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.route('**/api/items', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify([{ id: 1, name: 'dragon-scale', rarity: 'legendary' }]),
    });
  });
  await page.goto('http://localhost:5000/pages/level-08/');
  await page.waitForSelector('text=dragon-scale');
  console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`page.route(pattern, handler)` intercepts network requests before they reach the server. Register routes **before** `page.goto()`.

```
await page.route('**/api/items', async (route) => {
  await route.fulfill({
    status: 200,
    contentType: 'application/json',
    body: JSON.stringify([{ name: 'dragon-scale' }]),
  });
});
await page.goto('http://localhost:5000/pages/level-08/');
```

Handler options:
• `route.fulfill()` — return a custom response
• `route.continue()` — pass through unchanged
• `route.abort()` — cancel the request
• `route.fetch()` then modify — intercept and alter the real response

