const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.route('**/api/coupon', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ code: 'ARCANE100', discount: 100, valid: true }),
    });
  });
  await page.goto('http://localhost:5000/pages/level-24/');
  await page.locator('#add-p1').click();
  await page.locator('#add-p2').click();
  await page.locator('#coupon-input').fill('ARCANE100');
  await page.locator('#apply-coupon').click();
  await page.locator('#checkout-btn').click();
  const success = page.locator('#checkout-success');
  await success.waitFor({ state: 'visible' });
  console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
This level combines route interception with multi-step user interaction. Key order of operations:

1. Set up route handler for `/api/coupon` before navigation
2. Navigate and add items to cart
3. Fill the coupon code and click Apply (triggers the intercepted fetch)
4. Click checkout and wait for the success element

```
