const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  await context.grantPermissions(['geolocation']);
  await context.setGeolocation({ latitude: 51.5074, longitude: -0.1278 });
  const page = await context.newPage();
  await page.goto('http://localhost:5000/pages/level-34/');
  await page.locator('#locate-btn').click();
  const display = page.locator('#location-display');
  await display.waitFor({ state: 'visible' });
  const latText = await page.locator('#lat-display').textContent();
  if (latText && latText.includes('51')) console.log('LEVEL_PASSED');
  await browser.close();
})();

