const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  await page.goto('http://localhost:5000/pages/level-43/');
  await page.locator('#username').fill('archmage');
  await page.locator('#password').fill('spellbound');
  await page.locator('#login-btn').click();
  await page.waitForSelector('#dashboard-panel', { state: 'visible' });
  const state = await context.storageState();
  const context2 = await browser.newContext({ storageState: state });
  const page2 = await context2.newPage();
  await page2.goto('http://localhost:5000/pages/level-43/');
  const dashVisible = await page2.locator('#dashboard-panel').isVisible();
  if (dashVisible) console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`context.storageState()` captures the current localStorage, sessionStorage, and cookies as a JSON snapshot. Pass it to a new context to restore the session.

```
// Save session
const state = await context.storageState();
const context2 = await browser.newContext({ storageState: state });
const page2 = await context2.newPage();
await page2.goto('http://localhost:5000/pages/level-43/');
// page2 starts with the same session as context
```

Save to disk with `context.storageState({ path: '/tmp/session.json' })`.

