const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const responses = [];
  page.on('response', (res) => responses.push({ url: res.url(), status: res.status() }));
  await page.goto('http://localhost:5000/pages/level-47/');
  await page.locator('#btn-prophecy').click();
  await page.waitForTimeout(1000);
  const match = responses.find((r) => r.url.includes('prophecy.json') && r.status === 200);
  if (match) console.log('LEVEL_PASSED');
  await browser.close();
})();

