const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-50/');
  const badge = page.getByTestId('hero-badge');
  const badgeText = await badge.textContent();
  const searchInput = page.getByPlaceholder('Search spells...');
  const icon = page.getByRole('img', { name: 'Arcane Staff' });
  await searchInput.waitFor({ state: 'visible' });
  await icon.waitFor({ state: 'visible' });
  if (badgeText && badgeText.trim() === 'Champion') console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
Playwright provides semantic locators that find elements by their accessible role or content — more resilient than CSS selectors:

• `page.getByTestId('id')` — finds by `data-testid` attribute
• `page.getByPlaceholder('text')` — finds by `placeholder` attribute
• `page.getByRole('img', { name: 'Alt text' })` — finds by ARIA role + label

```
const badge = page.getByTestId('hero-badge');
const text = await badge.textContent();
const search = page.getByPlaceholder('Search spells...');
await search.waitFor({ state: 'visible' });
if (text.trim() === 'Champion') console.log('LEVEL_PASSED');
```

