const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-52/');
  const power = await page.locator('#power-crystal').evaluate(el => el.dataset.power);
  const spellName = await page.locator('#spell-name').evaluate(el => el.textContent.trim());
  if (power === '9000' && spellName === 'Ancient Fireball') console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`locator.evaluate(fn, arg?)` runs a function in the browser with the matched element as the first argument — combines locator + evaluate in one step.

```
const className = await page.locator('#hero-card').evaluate(el => el.className);
const style     = await page.locator('#hero-card').evaluate(el => el.style.color);
const checked   = await page.locator('#checkbox').evaluate(el => el.checked);
```

More targeted than `page.evaluate` — you don't need to re-query the element inside the browser function.

