  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-54/');
  const fireBtn = page.getByRole('button').and(page.getByText('Fire Strike'));
  const fireText = await fireBtn.textContent();
  const combined = page.locator('.spell').or(page.locator('.rune'));
  const count = await combined.count();
  if (fireText && fireText.includes('Fire Strike') && count === 6) console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
Playwright locators support composing multiple conditions:

• `.and(other)` — element must match BOTH locators
• `.or(other)` — element matches EITHER locator

```
