const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-56/');
  await page.waitForFunction(() => {
    const el = document.getElementById('mana-counter');
    return el && parseInt(el.textContent) >= 5;
  }, { timeout: 15000 });
  const value = await page.locator('#mana-counter').textContent();
  if (parseInt(value) >= 5) console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`page.waitForFunction(fn)` runs a JavaScript predicate in the browser and waits until it returns `true`. Useful for polling DOM state that changes over time.

```
await page.waitForFunction(() => {
  const el = document.getElementById('mana-counter');
  return el && parseInt(el.textContent) >= 5;
}, { timeout: 15000 });
const value = await page.locator('#mana-counter').textContent();
if (parseInt(value) >= 5) console.log('LEVEL_PASSED');
```

The function runs in the browser context — use `document`, `window`, but not Node.js APIs.

