const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:5000/pages/level-83/');
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.click('#download-btn'),
  ]);
  const name = download.suggestedFilename();
  if (name === 'report.txt') console.log('LEVEL_PASSED');
  await browser.close();
})();

explanation:
`page.waitForEvent('download')` captures a download triggered by a click. Use `Promise.all` to start listening **before** the click — otherwise you may miss the event.

```
const [download] = await Promise.all([
  page.waitForEvent('download'),   // start listening first
  page.click('#download-btn'),     // trigger the download second
]);
const name = download.suggestedFilename();
console.log('Downloaded:', name);
if (name === 'report.txt') console.log('LEVEL_PASSED');
```

The `download` object has:
• `suggestedFilename()` — the file name the server suggested
• `path()` — temp file path (async)
• `saveAs(path)` — save to a specific location
• `cancel()` — cancel an in-progress download

