  it('clicks the Reveal Secret button', () => {
      cy.visit('/pages/level-02/');
      cy.contains('button', 'Reveal Secret').click();
      cy.get('#secret-message').should('be.visible');
    });
});

explanation:
`cy.get(selector).click()` clicks the matched element. Cypress automatically waits for it to be visible and not disabled before clicking.

```
cy.get('#reveal-btn').click();
cy.get('#secret-message').should('contain', 'Playwright rocks');
```

For multiple clicks: `.dblclick()`, `.rightclick()`. For clicking inside a specific area: `.click('topLeft')`.

