import React from 'react';
import { LoginForm } from '../../components/LoginForm.jsx';

describe('The Login Crucible', () => {
  it('calls the onLogin stub when valid credentials are submitted', () => {
    const onLogin = cy.stub().as('onLoginStub');
    cy.mount(<LoginForm onLogin={onLogin} />);
    cy.get('[data-testid="username-input"]').type('admin');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="submit-btn"]').click();
    cy.get('@onLoginStub').should('have.been.calledOnce');
  });

  it('shows a validation error for empty fields', () => {
    const onLogin = cy.stub().as('onLoginStub');
    cy.mount(<LoginForm onLogin={onLogin} />);
    cy.get('[data-testid="submit-btn"]').click();
    cy.get('@onLoginStub').should('not.have.been.called');
  });
});

