describe('The Attribute Inspector', () => {
  beforeEach(() => {
    cy.visit('/pages/level-77/');
  });

  it('uses have.attr, have.id, and have.data on DOM elements', () => {
    cy.get('#hero').should('have.attr', 'title', 'Main Hero');
    cy.get('#quest-link').should('have.attr', 'href', '/quest').and('have.attr', 'target', '_blank');
