function throttle(fn, limit) {
  let lastRun = 0;
  return function (...args) {
    const now = Date.now();
    if (now - lastRun >= limit) {
      lastRun = now;
      fn(...args);
    }
  };
}

test('throttle — limits calls', () => {
  const fn = jest.fn();
  const throttled = throttle(fn, 1000);

  throttled();
  throttled();
  throttled();
