afterEach(() => { expect(counter).not.toBeNull(); });
test('starts at 0', () => { expect(counter).toBe(0); });
test('increments', () => { counter++; expect(counter).toBe(1); });
test('resets', () => { expect(counter).toBe(0); });
```

