class TrafficLight {
  constructor() {
    this.state = 'red';
    this.listeners = [];
    this.transitions = { red: 'green', green: 'yellow', yellow: 'red' };
  }
  onChange(fn) { this.listeners.push(fn); }
  next() {
    const prev = this.state;
    this.state = this.transitions[this.state];
    this.listeners.forEach(fn => fn(this.state, prev));
  }
