  expect(min(5, 3)).toBe(3);
  expect(min(3, 5)).toBe(3);
  expect(min(5, 5)).toBe(5);
  expect(min(-1, 0)).toBe(-1);
});

test('between catches off-by-one mutations', () => {
  expect(between(5, 1, 10)).toBe(true);
  expect(between(1, 1, 10)).toBe(false);
  expect(between(10, 1, 10)).toBe(false);
  expect(between(0, 1, 10)).toBe(false);
});

explanation:
Mutation testing modifies your source code in small ways (flipping `>` to `>=`, changing a constant, deleting a line) and checks whether your tests detect the change. A test suite that passes all mutations is over-specified. A suite where mutations go undetected is under-specified. Write assertions that are tight enough to catch off-by-one errors and boundary mutations.

```
