  expect(max(5, 3)).toBe(5);
  expect(max(3, 5)).toBe(5);
  expect(max(5, 5)).toBe(5);
  expect(max(-1, 0)).toBe(0);
});

test('min catches mutations', () => {
  expect(min(5, 3)).toBe(3);
  expect(min(3, 5)).toBe(3);
  expect(min(5, 5)).toBe(5);
  expect(min(-1, 0)).toBe(-1);
