Vitest supports multiple test environments: `node` (the default), `jsdom` (browser globals), and `happy-dom`. The environment is set via the `environment` option in vitest.config or per file with a `@vitest-environment` docblock comment. `jsdom` gives you `window`, `document`, and `localStorage`. `node` gives you `process` and Node built-ins. Choose the environment that matches your code's runtime.

```
import { test, expect, beforeEach, afterEach } from 'vitest';

class TestEnvironment {
  private cleanupTasks: Array<() => void> = [];
  register(task: () => void) { this.cleanupTasks.push(task); }
  cleanup() { this.cleanupTasks.forEach(t => t()); this.cleanupTasks = []; }
}

let env: TestEnvironment;

beforeEach(() => { env = new TestEnvironment(); });
afterEach(() => { env.cleanup(); });

test('cleanup tasks run after test', () => {
  const log: string[] = [];
  env.register(() => log.push('cleanup1'));
  env.register(() => log.push('cleanup2'));
  expect(log).toHaveLength(0);
  env.cleanup();
  expect(log).toEqual(['cleanup1', 'cleanup2']);
});

test('env is fresh for each test', () => {
  expect(env).toBeDefined();
  const log: string[] = [];
  env.register(() => log.push('only-one'));
  env.cleanup();
  expect(log).toHaveLength(1);
});
```

