import { test, expect, vi, beforeEach } from 'vitest';

class ApiClient {
  constructor(private baseUrl: string, private token: string) {}

  async get<T>(path: string): Promise<T> {
    const res = await fetch(\`\${this.baseUrl}\${path}\`, {
      headers: { Authorization: \`Bearer \${this.token}\` },
    });
    if (!res.ok) throw new Error(\`HTTP \${res.status}: \${path}\`);
    return res.json();
  }

  async post<T>(path: string, body: unknown): Promise<T> {
    const res = await fetch(\`\${this.baseUrl}\${path}\`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: \`Bearer \${this.token}\` },
      body: JSON.stringify(body),
    });
    if (!res.ok) throw new Error(\`HTTP \${res.status}: \${path}\`);
    return res.json();
  }
}

beforeEach(() => { vi.restoreAllMocks(); });

test('ApiClient.get calls fetch with correct headers', async () => {
  const mockFetch = vi.fn().mockResolvedValue({
    ok: true,
    json: async () => ({ id: 1, name: 'Alice' }),
  });
  vi.stubGlobal('fetch', mockFetch);

  const client = new ApiClient('https://api.test.com', 'my-token');
  const user = await client.get('/users/1');

  expect(mockFetch).toHaveBeenCalledWith(
    'https://api.test.com/users/1',
    expect.objectContaining({ headers: expect.objectContaining({ Authorization: 'Bearer my-token' }) })
  );
  expect(user).toEqual({ id: 1, name: 'Alice' });
  vi.unstubAllGlobals();
});

test('ApiClient.get throws on non-ok response', async () => {
  vi.stubGlobal('fetch', vi.fn().mockResolvedValue({ ok: false, status: 404, json: async () => ({}) }));
  const client = new ApiClient('https://api.test.com', 'token');
  await expect(client.get('/missing')).rejects.toThrow('HTTP 404');
  vi.unstubAllGlobals();
});

explanation:
An HTTP client wraps `fetch` with base URL construction, auth headers, and error handling. Mock `fetch` using `vi.stubGlobal('fetch', vi.fn())` and return a controlled `Response` object. Assert that the client sends the correct URL, headers, and body. Test the error path by returning a non-OK status code and verifying the client throws or returns the right error object.

