A TTL cache stores entries with an expiry timestamp. `get()` returns `null` if the entry is missing or expired. `set()` records the value with the current time plus TTL. Use `vi.useFakeTimers()` and `vi.setSystemTime()` to advance the clock past the TTL and verify the entry is evicted. Also test that a fresh set after expiry creates a new entry.

```
import { test, expect, vi } from 'vitest';

vi.useFakeTimers();

class TtlCache<K, V> {
  private store = new Map<K, { value: V; expiresAt: number }>();

  constructor(private ttlMs: number) {}

  set(key: K, value: V): void {
    this.store.set(key, { value, expiresAt: Date.now() + this.ttlMs });
  }

  get(key: K): V | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (Date.now() > entry.expiresAt) { this.store.delete(key); return undefined; }
    return entry.value;
  }

  has(key: K): boolean { return this.get(key) !== undefined; }
  size(): number { return this.store.size; }
}

test('TtlCache stores and retrieves values', () => {
  const cache = new TtlCache<string, number>(5000);
  cache.set('a', 1);
  cache.set('b', 2);
  expect(cache.get('a')).toBe(1);
  expect(cache.has('b')).toBe(true);
  expect(cache.get('x')).toBeUndefined();
});

test('TtlCache expires entries after TTL', () => {
  const cache = new TtlCache<string, string>(1000);
  cache.set('key', 'value');
  expect(cache.get('key')).toBe('value');
  vi.advanceTimersByTime(1001);
  expect(cache.get('key')).toBeUndefined();
  expect(cache.has('key')).toBe(false);
});

vi.useRealTimers();
