import { test, expect } from 'vitest';

interface Command { execute(): void; undo(): void; }

class CommandQueue {
  private history: Command[] = [];
  private redoStack: Command[] = [];

  execute(cmd: Command): void {
    cmd.execute();
    this.history.push(cmd);
    this.redoStack = [];
  }

  undo(): void {
    const cmd = this.history.pop();
    if (cmd) { cmd.undo(); this.redoStack.push(cmd); }
  }

  redo(): void {
    const cmd = this.redoStack.pop();
    if (cmd) { cmd.execute(); this.history.push(cmd); }
  }

  get canUndo() { return this.history.length > 0; }
  get canRedo() { return this.redoStack.length > 0; }
}

test('CommandQueue execute and undo', () => {
  const queue = new CommandQueue();
  let value = 0;

  queue.execute({ execute: () => { value += 10; }, undo: () => { value -= 10; } });
  queue.execute({ execute: () => { value *= 2; }, undo: () => { value /= 2; } });
  expect(value).toBe(20);

  queue.undo();
  expect(value).toBe(10);

  queue.undo();
  expect(value).toBe(0);
  expect(queue.canUndo).toBe(false);
});

test('CommandQueue redo restores state', () => {
  const queue = new CommandQueue();
  let count = 0;
  const incCmd = { execute: () => count++, undo: () => count-- };

  queue.execute(incCmd);
  queue.execute(incCmd);
  expect(count).toBe(2);
  queue.undo();
  expect(count).toBe(1);
  expect(queue.canRedo).toBe(true);
  queue.redo();
  expect(count).toBe(2);
});

explanation:
The command pattern stores each action as an object with `execute()` and `undo()` methods. A command queue pushes executed commands onto a history stack. Undo pops the stack and calls `undo()`. Test that state after execute → undo → execute again matches the expected sequence. Also test that undo on an empty stack throws or is a no-op.

