import { test, expect } from 'vitest';

test('stable function always returns same result', { repeats: 4 }, () => {
  const stable = (x) => x * 2;
  expect(stable(5)).toBe(10);
});

test('Math.random is always in [0,1)', { repeats: 10 }, () => {
  const r = Math.random();
  expect(r).toBeGreaterThanOrEqual(0);
  expect(r).toBeLessThan(1);
});

test('Date.now increases or stays same between calls', { repeats: 3 }, () => {
  const t1 = Date.now();
  const t2 = Date.now();
  expect(t2).toBeGreaterThanOrEqual(t1);
});

test('array sort is deterministic', { repeats: 5 }, () => {
  const arr = [3, 1, 4, 1, 5, 9, 2, 6];
  const sorted = [...arr].sort((a, b) => a - b);
  expect(sorted[0]).toBe(1);
  expect(sorted[sorted.length - 1]).toBe(9);
});

explanation:
`test.repeats(n)` runs the same test `n` times in sequence. Use it to catch flaky tests that fail intermittently — if any repetition fails, the test is marked as failed. Helpful for race conditions or non-deterministic code.

```
import { test, expect } from 'vitest';

test('stable function always returns same result', { repeats: 4 }, () => {
  const stable = (x) => x * 2;
  expect(stable(5)).toBe(10);
});

test('Math.random is always in [0,1)', { repeats: 10 }, () => {
  const r = Math.random();
  expect(r).toBeGreaterThanOrEqual(0);
  expect(r).toBeLessThan(1);
});

test('Date.now increases or stays same between calls', { repeats: 3 }, () => {
  const t1 = Date.now();
  const t2 = Date.now();
  expect(t2).toBeGreaterThanOrEqual(t1);
});

test('array sort is deterministic', { repeats: 5 }, () => {
  const arr = [3, 1, 4, 1, 5, 9, 2, 6];
  const sorted = [...arr].sort((a, b) => a - b);
  expect(sorted[0]).toBe(1);
  expect(sorted[sorted.length - 1]).toBe(9);
});
