import { expect, test } from 'vitest'

const userSchema = {
  type: 'object',
  properties: {
    id: { type: 'integer' },
    name: { type: 'string' },
    age: { type: 'integer' }
  },
  required: ['id', 'name']
}

test('user object matches schema', () => {
  const user = { id: 1, name: 'Alice', age: 30 }
  expect(user).toEqual(expect.schemaMatching(userSchema))
})

test('minimal user matches schema', () => {
  expect({ id: 2, name: 'Bob' }).toEqual(expect.schemaMatching(userSchema))
})

test('array of users each match schema', () => {
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]
  for (const u of users) {
    expect(u).toEqual(expect.schemaMatching(userSchema))
  }
})

explanation:
`expect.schemaMatching(schema)` validates that a value matches a Zod (or compatible) schema. The assertion fails with a detailed error message listing every field that doesn't conform — much more informative than checking individual properties.

