from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch()
    page = browser.new_page()
    report = {}
    for n in ['01', '02', '03']:
        page.goto(f'http://localhost:5000/pages/level-{n}/')
        report[n] = {'title': page.title(), 'h1': page.locator('h1').text_content()}
    if all(v['title'] and v['h1'] for v in report.values()):
        print('LEVEL_PASSED')
    browser.close()

from playwright.sync_api import sync_playwright

urls = ['http://localhost:5000/pages/level-01/', 'http://localhost:5000/pages/does-not-exist/', 'http://localhost:5000/pages/level-02/']
with sync_playwright() as p:
    browser = p.chromium.launch()
    page = browser.new_page()
    successes = 0
    for url in urls:
        try:
            page.goto(url, timeout=3000)
            if page.locator('h1').count() > 0:
                successes += 1
        except Exception:
            pass
    if successes >= 2:
        print('LEVEL_PASSED')
    browser.close()
